              "statusText": "快开始"
            },
            "properties": {
              "entityId": {
                "type": "string",
                "description": "日程唯一标识，用于点击后打开系统日历详情。",
                "sampleValue": "calendar-event-1001"
              },
              "title": {
                "type": "string",
                "description": "日程标题。",
                "sampleValue": "产品评审"
              },
              "dtStart": {
                "type": "string",
                "description": "日程开始时间，当天日程通常为 HH:MM 格式。",
                "sampleValue": "14:30"
              },
              "dtEnd": {
                "type": "string",
                "description": "日程结束时间，当天日程通常为 HH:MM 格式。",
                "sampleValue": "15:00"
              },
              "eventLocation": {
                "type": "string",
                "description": "日程发生地点。",
                "sampleValue": "3号会议室"
              },
              "remindTime": {
                "type": "array",
                "description": "日程提醒时间文本列表。",
                "sampleValue": [
                  "提前10分钟"
                ],
                "items": {
                  "type": "string",
                  "description": "单个提醒时间文本。",
                  "sampleValue": "提前10分钟"
                }
              },
              "countdownText": {
                "type": "string",
                "description": "距离日程开始的倒计时数字文本，由日历服务或运行时刷新。",
                "sampleValue": "12"
              },
              "countdownUnit": {
                "type": "string",
                "description": "倒计时单位。",
                "sampleValue": "分钟"
              },
              "statusText": {
                "type": "string",
                "description": "临近日程开始时的提醒状态文本。",
                "sampleValue": "快开始"
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": []
}

